const json=(x,s=200,h={})=>{if(s&&typeof s==="object"){h=s;s=200}return new Response(JSON.stringify(x),{status:s,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store",...h}})};
const txt=(x,s=200,h={})=>new Response(x,{status:s,headers:h});
const now=()=>new Date().toISOString();
const val=v=>v===undefined||v===null?null:typeof v==="boolean"?(v?1:0):typeof v==="object"?JSON.stringify(v):v;
function ident(v){const s=String(v);if(!IDENT.test(s))throw new Error("Invalid identifier.");return '"'+s+'"'}
function normalize(r){if(!r||typeof r!=="object")return r;const o={...r};for(const k of Object.keys(o))if((o[k]===0||o[k]===1)&&BOOLS.has(k))o[k]=!!o[k];for(const k of ["payment_methods","content","business_koro_order_ids"])if(typeof o[k]==="string")try{o[k]=JSON.parse(o[k])}catch{}return o}
async function q(env,sql,params=[]){if(!env.DB)throw new Error("Cloudflare D1 binding DB is missing.");return env.DB.prepare(sql).bind(...params.map(val)).all()}
function getCookie(req,name){const raw=req.headers.get("Cookie")||"";for(const p of raw.split(";")){const a=p.trim().split("=");if(a[0]===name)return decodeURIComponent(a.slice(1).join("="))}return ""}
async function sha(v){return [...new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(String(v))))].map(x=>x.toString(16).padStart(2,"0")).join("")}
function b64(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/=/g,"").replace(/\+/g,"-").replace(/\//g,"_")}
function ub64(s){s=String(s).replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function hmac(secret,data){const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return new Uint8Array(await crypto.subtle.sign("HMAC",k,new TextEncoder().encode(data)))}
async function makeBridge(user,secret){const key=String(secret||"");if(!key)throw new Error("Admin authentication secret is not configured.");const p=b64(new TextEncoder().encode(JSON.stringify({sub:user.id,email:user.email,exp:Math.floor(Date.now()/1000)+604800})));return p+"."+b64(await hmac(key,p))}
async function verifyBridge(t,secret){if(!t||!secret)return null;const a=String(t).split(".");if(a.length!==2)return null;const e=await hmac(secret,a[0]),g=ub64(a[1]);if(e.length!==g.length)return null;let d=0;for(let i=0;i<e.length;i++)d|=e[i]^g[i];if(d)return null;try{const p=JSON.parse(new TextDecoder().decode(ub64(a[0])));return p?.sub&&p?.email&&Number(p.exp)>Date.now()/1000?p:null}catch{return null}}
async function ensureAuth(env){await ensureSchema(env);await env.DB.prepare("CREATE TABLE IF NOT EXISTS admin_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)").run();await env.DB.prepare("CREATE TABLE IF NOT EXISTS admin_sessions(token_hash TEXT PRIMARY KEY,admin_user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL)").run()}
async function pbkdf(p,s){const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(p),"PBKDF2",false,["deriveBits"]);const b=await crypto.subtle.deriveBits({name:"PBKDF2",salt:new TextEncoder().encode(s),iterations:100000,hash:"SHA-256"},k,256);return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function session(req,env){const raw=getCookie(req,"gz_admin_session");if(raw){const r=await q(env,"SELECT u.id,u.email FROM admin_sessions s JOIN admin_users u ON u.id=s.admin_user_id WHERE s.token_hash=? AND s.expires_at>? LIMIT 1",[await sha(raw),now()]);if(r.results?.[0])return r.results[0]}const a=req.headers.get("Authorization")||"",x=req.headers.get("X-GrabZone-Token")||"",bearer=a.startsWith("Bearer ")?a.slice(7).trim():x;if(bearer){const direct=(await q(env,"SELECT u.id,u.email FROM admin_sessions s JOIN admin_users u ON u.id=s.admin_user_id WHERE s.token_hash=? AND s.expires_at>? LIMIT 1",[await sha(bearer),now()])).results?.[0];if(direct)return direct;let p=await verifyBridge(bearer,env.D1_AUTH_SECRET||env.GRABZONE_ADMIN_PASSWORD);if(!p){try{const part=String(bearer).split(".");if(part.length===2){const unsigned=JSON.parse(new TextDecoder().decode(ub64(part[0])));if(unsigned?.sub){const u=(await q(env,"SELECT id,email,password_hash FROM admin_users WHERE id=? LIMIT 1",[unsigned.sub])).results?.[0];if(u){p=await verifyBridge(bearer,u.password_hash);if(p&&p.email===u.email)return{id:u.id,email:u.email}}}}}catch{}}if(p)return{id:p.sub,email:p.email}}return null}
async function bootstrap(env){const email=String(env.GRABZONE_ADMIN_EMAIL||"").trim().toLowerCase(),pass=String(env.GRABZONE_ADMIN_PASSWORD||"");if(!email||!pass)return;const r=await q(env,"SELECT id,email FROM admin_users WHERE lower(email)=lower(?) LIMIT 1",[email]);if(r.results?.[0])return;const id=crypto.randomUUID(),salt=crypto.randomUUID()+crypto.randomUUID(),t=now();await env.DB.prepare("INSERT INTO admin_users(id,email,password_hash,password_salt,created_at,updated_at) VALUES(?,?,?,?,?,?)").bind(id,email,await pbkdf(pass,salt),salt,t,t).run()}
async function auth(req,env){await ensureAuth(env);await bootstrap(env);if(req.method==="GET"){const s=await session(req,env);if(!s)return json({authenticated:false,user:null,session_token:null});const raw=crypto.randomUUID().replace(/-/g,"")+crypto.randomUUID().replace(/-/g,""),t=now(),exp=new Date(Date.now()+604800000).toISOString();await env.DB.prepare("INSERT INTO admin_sessions(token_hash,admin_user_id,expires_at,created_at) VALUES(?,?,?,?)").bind(await sha(raw),s.id,exp,t).run();const u=(await q(env,"SELECT id,email,password_hash FROM admin_users WHERE id=? LIMIT 1",[s.id])).results?.[0];return json({authenticated:true,user:{id:s.id,email:s.email},session_token:raw,expires_at:exp},200,{"Set-Cookie":"gz_admin_session="+encodeURIComponent(raw)+"; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax"})}if(req.method!=="POST")return json({error:"Method not allowed."},405);let b={};try{b=await req.json()}catch{}if(b.action==="logout"){const raw=getCookie(req,"gz_admin_session");if(raw)await env.DB.prepare("DELETE FROM admin_sessions WHERE token_hash=?").bind(await sha(raw)).run();return json({ok:true},200,{"Set-Cookie":"gz_admin_session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax"})}const email=String(b.email||"").trim().toLowerCase(),pass=String(b.password||"");if(!email||!pass)return json({error:"Enter your admin email and password."},400);let u=(await q(env,"SELECT * FROM admin_users WHERE lower(email)=lower(?) LIMIT 1",[email])).results?.[0]||null;let valid=false;if(u)try{valid=await pbkdf(pass,u.password_salt)===u.password_hash}catch{}if(!valid&&email===String(env.GRABZONE_ADMIN_EMAIL||"").trim().toLowerCase()&&pass===String(env.GRABZONE_ADMIN_PASSWORD||"")){const id=u?.id||crypto.randomUUID(),salt=crypto.randomUUID()+crypto.randomUUID(),t=now(),hash=await pbkdf(pass,salt);if(u)await env.DB.prepare("UPDATE admin_users SET password_hash=?,password_salt=?,updated_at=? WHERE id=?").bind(hash,salt,t,id).run();else await env.DB.prepare("INSERT INTO admin_users(id,email,password_hash,password_salt,created_at,updated_at) VALUES(?,?,?,?,?,?)").bind(id,email,hash,salt,t,t).run();u={id,email};valid=true}if(!valid)return json({error:"Invalid email or password."},401);const raw=crypto.randomUUID().replace(/-/g,"")+crypto.randomUUID().replace(/-/g,""),t=now(),exp=new Date(Date.now()+604800000).toISOString();await env.DB.prepare("DELETE FROM admin_sessions WHERE expires_at<?").bind(t).run();await env.DB.prepare("INSERT INTO admin_sessions(token_hash,admin_user_id,expires_at,created_at) VALUES(?,?,?,?)").bind(await sha(raw),u.id,exp,t).run();return json({ok:true,user:{id:u.id,email:u.email},expires_at:exp,session_token:raw},200,{"Set-Cookie":"gz_admin_session="+encodeURIComponent(raw)+"; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax"})}
function whereSql(fs,ps){const a=[];for(const f of fs||[]){const c=ident(f.column);if(f.op==="eq"){a.push(c+"=?");ps.push(val(f.value))}else if(f.op==="neq"){a.push(c+"<>?");ps.push(val(f.value))}else if(f.op==="gt"){a.push(c+">?");ps.push(val(f.value))}else if(f.op==="gte"){a.push(c+">=?");ps.push(val(f.value))}else if(f.op==="lt"){a.push(c+"<?");ps.push(val(f.value))}else if(f.op==="lte"){a.push(c+"<=?");ps.push(val(f.value))}else if(f.op==="is")a.push(f.value===null?c+" IS NULL":c+" IS NOT NULL");else if(f.op==="in"){const x=Array.isArray(f.value)?f.value:[];if(!x.length)a.push("1=0");else{a.push(c+" IN("+x.map(()=>"?").join(",")+")");x.forEach(v=>ps.push(val(v)))}}else throw new Error("Unsupported filter.")}return a.length?" WHERE "+a.join(" AND "):""}
