async function business(req,env){
 const s=await session(req,env);
 if(!s)return json({error:"Unauthorized."},401);
 if(!env.BUSINESS_KORO_API_KEY)return json({error:"Business Koro integration is not configured."},503);
 let b={};try{b=await req.json()}catch{}
 let order=null,items=[],customer=b.customer||{},orderNumber=String(b.orderNumber||b.order_number||"").trim();
 const requestedId=String(b.orderId||b.order_id||"").trim();
 if(requestedId){
  order=(await q(env,"SELECT * FROM orders WHERE id=? LIMIT 1",[requestedId])).results?.[0]||null;
  if(!order)order=(await q(env,"SELECT * FROM orders WHERE order_number=? LIMIT 1",[requestedId])).results?.[0]||null;
 }
 if(!order&&orderNumber)order=(await q(env,"SELECT * FROM orders WHERE order_number=? LIMIT 1",[orderNumber])).results?.[0]||null;
 if(requestedId||orderNumber){
  if(order){
   if(order.business_koro_sent_at&&!b.force)return json({error:"This order has already been sent to Business Koro."},409);
   items=(await q(env,"SELECT * FROM order_items WHERE order_id=? ORDER BY id",[order.id])).results||[];
   customer={name:order.customer_name,phone:order.phone,address:order.address,division:order.division,district:order.district,area:order.upazila,note:order.admin_note||""};
   orderNumber=order.order_number;
  }else if(!Array.isArray(b.items)||!b.items.length){
   return json({error:"Order not found in GrabZone D1 and no order data was provided."},404);
  }
 }
 if(!items.length)items=Array.isArray(b.items)?b.items:[];
 if(!items.length)return json({error:"This order has no products."},400);
 const pr=await fetch("https://api.businesskoro.com/api/v1/storefront/products",{headers:{"x-api-key":env.BUSINESS_KORO_API_KEY,Accept:"application/json"}});
 const pd=await pr.json().catch(()=>({}));
 if(!pr.ok)return json({error:pd?.message||pd?.error||"Could not load Business Koro products."},502);
 const list=Array.isArray(pd?.data)?pd.data:[];
 const norm=v=>String(v||"").toLowerCase().normalize("NFKC").replace(/[^a-z0-9\u0980-\u09ff]+/g," ").trim().replace(/\s+/g," ");
 const out=[];
 for(const i of items){
  let pid=String(i.business_koro_product_id||i.productId||"").trim();
  if(!pid&&i.product_id){
   const p=(await q(env,"SELECT business_koro_product_id FROM products WHERE id=? LIMIT 1",[String(i.product_id)])).results?.[0];
   pid=String(p?.business_koro_product_id||"").trim();
  }
  if(!pid){
   const m=list.filter(x=>norm(x.name)===norm(i.productName||i.product_name));
   if(m.length===1)pid=String(m[0].id);
  }
  if(!pid)return json({error:'Business Koro product ID is missing for "'+String(i.productName||i.product_name||"Unknown product")+'". Set the Business Koro product ID on this GrabZone product.'},400);
  const quantity=Math.max(1,Number(i.quantity||1));
  for(let n=0;n<quantity;n++){
   const rr=await fetch("https://api.businesskoro.com/api/v1/storefront/orders",{method:"POST",headers:{"x-api-key":env.BUSINESS_KORO_API_KEY,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({
    productId:pid,customerName:customer.name,customerPhone:customer.phone,customerAddress:customer.address,customerDivision:customer.division,customerDistrict:customer.district,customerArea:customer.area||"",sellingPrice:Number(i.sellingPrice??i.unit_price??0),deliveryChargePaidByCustomer:true,customerNote:[orderNumber,customer.note].filter(Boolean).join(" — ")
   })});
   const d=await rr.json().catch(()=>({}));
   if(!rr.ok)return json({error:d?.message||d?.error||d?.errors?.[0]?.message||"Business Koro rejected the order.",businessKoroStatus:rr.status},502);
   out.push({productId:pid,productName:i.productName||i.product_name,unit:n+1,supplierOrderId:d?.id||d?.orderId||d?.order_id||d?.data?.id||null});
  }
 }
 if(order)await env.DB.prepare("UPDATE orders SET business_koro_sent_at=?,business_koro_order_ids=?,updated_at=? WHERE id=?").bind(now(),JSON.stringify(out.map(x=>x.supplierOrderId)),now(),order.id).run();
 return json({success:true,orderNumber,submitted:out.length,orders:out});
}
